/**
 * The Ark's vertical layers (docs/ark-micro.md, "Layers"; the owner's
 * addendum): the canopy over the ground, the ground (its zones, the cottage
 * and the microhabitats), the underground beneath it, and the sea round the
 * island (the shallow reef, the open water, the deep). The island does not
 * grow: the layers stack on it, and each zone can take more later.
 *
 * Which layer a species lives in is `layers.json`, generated by
 * `scripts/ark-layers.mts` from stored data (zone, realm, body plan, habitat
 * text, taxonomy; the deciding phrase kept). Here: the lookup, and the
 * canopy's and the underground's places, each a pure function of the
 * animal's zone, slot and rank, like every other place (nobody moves).
 *
 * Visual only: the layers decide nothing that happens. The ecology's realm
 * filter already keeps land, water and air apart.
 */

import table from "@/ark-scene/layers.json";
import {worldDecor, type DecorItem} from "@/ark-scene/decor";
import {canopyTree, CANOPY_TREES, DECOR_SINK, limbAt} from "@/ark-scene/micro-decor";
import {ARK_ZONES, type ArkZone} from "@/ark-scene/types";
import {hashString, ZONE_SITES} from "@/ark-scene/world";

export type ArkLayer = "canopy" | "ground" | "underground" | "reef" | "open_sea" | "deep";
/** How it lives in its layer: perch, climb, leap, hang (canopy); dig (underground); swim, floor, filter (sea). */
export type LayerMode = "perch" | "climb" | "leap" | "hang" | "dig" | "swim" | "floor" | "filter" | "";

export type SpeciesLayer = {
    layer: ArkLayer;
    mode: LayerMode;
    /** The stored phrase (or the zone, or the taxonomy) that decided it. */
    reason: string;
    /** A burrow's entrance is drawn by it (a ground animal that digs). */
    burrow: boolean;
    /** It glows at night (its text says it is bioluminescent). */
    glow: boolean;
    /** A primate (the canopy's climbers that drop to the ground now and then). */
    primate: boolean;
};

type Row = [string, string, string] | [string, string, string, string];
const ROWS = (table as unknown as {species: Record<string, Row>}).species;
const known = new Map<string, SpeciesLayer>();

const GROUND: SpeciesLayer = {layer: "ground", mode: "", reason: "", burrow: false, glow: false, primate: false};

/** A species' layer: the table's row, else the ground. */
export function speciesLayer(slug: string): SpeciesLayer {
    let found = known.get(slug);
    if (!found) {
        const row = ROWS[slug];
        found = row ? {layer: row[0] as ArkLayer, mode: row[1] as LayerMode, reason: row[2], burrow: (row[3] ?? "").includes("b"), glow: (row[3] ?? "").includes("g"), primate: (row[3] ?? "").includes("p")} : GROUND;
        known.set(slug, found);
    }
    return found;
}

// MARK: The canopy

export type CanopyPlace = {
    /** Which tree of the zone's, which limb of it (-1: the crown, -2: the trunk). */
    tree: number;
    limb: number;
    /** Along the limb (0 at the trunk), or round the crown or the trunk. */
    a: number;
    b: number;
    mode: LayerMode;
    /** Its rank's offset along the limb (m). */
    offset: number;
    /** Whose trees (the map: the zone of the tree it was given); else the animal's own zone's. */
    zone?: ArkZone;
};

export type CanopyHost = {item: DecorItem; zone: ArkZone};
const treesByZone = new Map<ArkZone, CanopyHost[]>();

/** A zone's canopy trees, nearest its ground first (a zone without its own borrows the nearest zone's that has them). */
export function canopyTrees(zone: ArkZone): CanopyHost[] {
    let list = treesByZone.get(zone);
    if (list) return list;
    const site = ZONE_SITES[zone];
    const all = worldDecor().filter((item) => item.kind === "canopy");
    const own = CANOPY_TREES[zone] ? all.filter((item) => nearestZone(item) === zone) : [];
    if (own.length) list = own.sort((p, q) => Math.hypot(p.x - site.x, p.z - site.z) - Math.hypot(q.x - site.x, q.z - site.z)).map((item) => ({item, zone}));
    else {
        // The nearest zone that has some.
        const zones = (Object.keys(CANOPY_TREES) as ArkZone[]).sort((p, q) => Math.hypot(ZONE_SITES[p].x - site.x, ZONE_SITES[p].z - site.z) - Math.hypot(ZONE_SITES[q].x - site.x, ZONE_SITES[q].z - site.z));
        list = canopyTrees(zones[0]);
    }
    treesByZone.set(zone, list);
    return list;
}

function nearestZone(item: DecorItem): ArkZone {
    let best: ArkZone = "farm_garden";
    let distance = Infinity;
    for (const zone of Object.keys(CANOPY_TREES) as ArkZone[]) {
        const site = ZONE_SITES[zone];
        const d = Math.hypot(item.x - site.x, item.z - site.z);
        if (d < distance) {
            distance = d;
            best = zone;
        }
    }
    return best;
}

const R2 = 1.324717957244746;

/**
 * A canopy animal's place from its zone, slot and rank: slot k of zone Z
 * takes point `k · 12 + Z` of the zone's limbs (a low-discrepancy sequence:
 * the tree and limb from one coordinate, how far along from the other),
 * its rank a step further along the same limb. Birds perch toward the tips
 * and on the crown; climbers and leapers sit nearer the trunk (one in three
 * on the trunk itself); hangers hang under a limb.
 */
export function canopyPlace(zone: ArkZone, slot: number, rank: number, mode: LayerMode, length: number): CanopyPlace | null {
    const trees = canopyTrees(zone);
    if (!trees.length) return null;
    const index = slot * ARK_ZONES.length + Math.max(ARK_ZONES.indexOf(zone), 0);
    const u = (0.5 + index / R2) % 1;
    const v = (0.5 + index / (R2 * R2)) % 1;
    const limbs = canopyTree(0).limbs.length;
    const slots = trees.length * limbs;
    const pick = Math.floor(u * slots);
    const tree = Math.floor(pick / limbs);
    // A cluster's members each on the next limb round (a troop spread through the tree).
    let limb = (pick + rank) % limbs;
    const hash = hashString(`${zone}#${slot}#canopy`);
    if (mode === "perch" && hash % 4 === 0) limb = -1;
    if (mode === "climb" && hash % 3 === 0) limb = -2;
    const a = mode === "perch" ? 0.45 + 0.4 * v : mode === "hang" ? 0.3 + 0.35 * v : 0.18 + 0.35 * v;
    return {tree: tree + Math.floor((pick % limbs + rank) / limbs), limb, a, b: ((hash >>> 8) % 1000) / 1000, mode, offset: rank >= limbs ? Math.max(length * 1.1, 0.25) : 0};
}

export type CanopyPoint = {x: number; y: number; z: number; nx: number; ny: number; nz: number; tx: number; ty: number; tz: number};

/** The tree's own metres turned into the world's. */
function world(item: DecorItem, x: number, y: number, z: number): [number, number, number] {
    const c = Math.cos(item.rotation);
    const s = Math.sin(item.rotation);
    return [item.x + (x * c + z * s) * item.scale, item.y - DECOR_SINK + y * item.scale, item.z + (-x * s + z * c) * item.scale];
}

function turn(item: DecorItem, x: number, y: number, z: number): [number, number, number] {
    const c = Math.cos(item.rotation);
    const s = Math.sin(item.rotation);
    return [x * c + z * s, y, -x * s + z * c];
}

/**
 * The point of a canopy place, `along` metres further along its limb (or up
 * its trunk): on top of the limb (its back up, heading along it), under it
 * for a hanger (its back down), on the crown's top, or on the trunk's bark.
 */
export function canopyPoint(zone: ArkZone, place: CanopyPlace, along = 0): CanopyPoint {
    const trees = canopyTrees(place.zone ?? zone);
    const host = trees[place.tree % trees.length];
    const tree = canopyTree(host.item.variant % 2);
    if (place.limb === -1) {
        // The crown: on its top, a little off the middle.
        const angle = place.b * Math.PI * 2;
        const r = 0.35 + 0.25 * place.a;
        const lx = Math.sin(angle) * r;
        const lz = Math.cos(angle) * r;
        const top = tree.crown.y + tree.crown.radius * tree.crown.squash * 1.02 - (r * r) / (2 * tree.crown.radius) * tree.crown.squash;
        const [x, y, z] = world(host.item, lx, top, lz);
        const [tx, , tz] = turn(host.item, Math.cos(angle), 0, -Math.sin(angle));
        return {x, y, z, nx: 0, ny: 1, nz: 0, tx, ty: 0, tz};
    }
    if (place.limb === -2) {
        // The trunk: on its bark, facing out, heading up it.
        const angle = place.b * Math.PI * 2;
        const h = Math.min(Math.max(1.2 + place.a * 3 + place.offset + along, 0.6), tree.limbs[0].height - 0.3);
        const r = tree.base + (tree.top - tree.base) * h / tree.height + 0.01;
        const [x, y, z] = world(host.item, Math.sin(angle) * r, h, Math.cos(angle) * r);
        const [nx, , nz] = turn(host.item, Math.sin(angle), 0, Math.cos(angle));
        return {x, y, z, nx, ny: 0, nz, tx: 0, ty: 1, tz: 0};
    }
    const limb = tree.limbs[place.limb % tree.limbs.length];
    const t = Math.min(Math.max(place.a + (place.offset + along) / limb.length, 0.12), 0.92);
    const at = limbAt(limb, tree.base, t);
    // Up, square to the limb.
    const dot = at.dy;
    let nx = -at.dx * dot;
    let ny = 1 - at.dy * dot;
    let nz = -at.dz * dot;
    const length = Math.hypot(nx, ny, nz) || 1;
    nx /= length;
    ny /= length;
    nz /= length;
    const side = place.mode === "hang" ? -1 : 1;
    const [x, y, z] = world(host.item, at.x + nx * at.radius * side, at.y + ny * at.radius * side, at.z + nz * at.radius * side);
    const [wnx, wny, wnz] = turn(host.item, nx * side, ny * side, nz * side);
    const [wtx, wty, wtz] = turn(host.item, at.dx, at.dy, at.dz);
    return {x, y, z, nx: wnx, ny: wny, nz: wnz, tx: wtx, ty: wty, tz: wtz};
}

/** For a leaper: the next limb up or down the same tree, at the same distance out (where it leaps to and back). */
export function leapTarget(place: CanopyPlace): CanopyPlace {
    const limbs = canopyTree(0).limbs.length;
    const limb = place.limb < 0 ? 0 : (place.limb + (place.b > 0.5 ? 1 : limbs - 1)) % limbs;
    return {...place, limb, offset: 0};
}

// MARK: The underground

/** A burrow: its entrance on the ground (the animal's spot), its tunnel down and along, its chamber at the end. */
export type Burrow = {x: number; z: number; ground: number; direction: number; depth: number; length: number};

/** The tunnel's line, from the entrance (t 0) down to the chamber (t 1). */
export function tunnelPoint(burrow: Burrow, t: number): {x: number; y: number; z: number} {
    // Down steeply over the first quarter, then along, gently deeper.
    const down = Math.min(t / 0.25, 1);
    const run = burrow.length * t;
    return {
        x: burrow.x + Math.sin(burrow.direction) * run,
        y: burrow.ground - burrow.depth * (0.75 * (1 - (1 - down) ** 2) + 0.25 * t),
        z: burrow.z + Math.cos(burrow.direction) * run
    };
}

/** An underground animal's burrow, from its spot and its id's hash: the tunnel runs off to one side, 0.6–0.9 m down. */
export function burrowAt(x: number, z: number, ground: number, seed: string, length: number): Burrow {
    const hash = hashString(`${seed}#burrow`);
    return {x, z, ground, direction: (hash % 360) / 180 * Math.PI, depth: 0.6 + ((hash >>> 9) % 100) / 100 * 0.3, length: Math.max(2.2, length * 4)};
}
